import{F as e,I as t,Z as n,t as r}from"./chunks/framework.Cmd5zirK.js";var i=JSON.parse(`{"title":"Benchmark","description":"","frontmatter":{},"headers":[],"relativePath":"usage/benchmark.md","filePath":"en/usage/benchmark.md","lastUpdated":1794127748000}`),a={name:`usage/benchmark.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="benchmark" tabindex="-1">Benchmark <a class="header-anchor" href="#benchmark" aria-label="Permalink to “Benchmark”">​</a></h1><p>All benchmark results are recorded here, see <a href="./../deep-dive/benchmarking">deep dive: benchmarking</a> for benchmarking details. Sync Engine welcomes everyone contributing benchmarking results as long as it follows the steps specified in the spec.</p><h2 id="apparent-statistics" tabindex="-1">Apparent Statistics <a class="header-anchor" href="#apparent-statistics" aria-label="Permalink to “Apparent Statistics”">​</a></h2><table tabindex="0"><thead><tr><th>Metrics</th><th>Sync Engine</th><th>Remotely Save</th><th>Nextcloud Sync</th><th>Nutstore Sync</th><th>Google Drive Sync</th><th>Easy Sync</th></tr></thead><tbody><tr><td>Version</td><td>3.3.4</td><td>0.5.25</td><td>1.0.13</td><td>1.6.0</td><td>3.1.1</td><td>1.6.5</td></tr><tr><td>Transparent<sup class="footnote-ref"><a href="#footnote1">[1]</a><a class="footnote-anchor" id="footnote-ref1"></a></sup></td><td>✅</td><td>⚠️<sup class="footnote-ref"><a href="#footnote2">[2]</a><a class="footnote-anchor" id="footnote-ref2"></a></sup></td><td>✅</td><td>⚠️<sup class="footnote-ref"><a href="#footnote3">[3]</a><a class="footnote-anchor" id="footnote-ref3"></a></sup></td><td>✅</td><td>✅</td></tr><tr><td>Startup time<sup class="footnote-ref"><a href="#footnote4">[4]</a><a class="footnote-anchor" id="footnote-ref4"></a></sup></td><td>27.2 ms<sup class="footnote-ref"><a href="#footnote5">[5]</a><a class="footnote-anchor" id="footnote-ref5"></a></sup></td><td>251 ms</td><td>20.2 ms</td><td>298ms</td><td>6.6ms</td><td>60.8ms</td></tr><tr><td>Plugin size</td><td>158 KB</td><td>4050 KB</td><td>595 KB</td><td>4230 KB</td><td>31.3 KB</td><td>1840 KB</td></tr><tr><td>Sync hidden files<sup class="footnote-ref"><a href="#footnote6">[6]</a><a class="footnote-anchor" id="footnote-ref6"></a></sup></td><td>✅</td><td>⚠️<sup class="footnote-ref"><a href="#footnote7">[7]</a><a class="footnote-anchor" id="footnote-ref7"></a></sup></td><td>⚠️<sup class="footnote-ref"><a href="#footnote7">[7:1]</a><a class="footnote-anchor" id="footnote-ref7:1"></a></sup></td><td>✅</td><td>⚠️<sup class="footnote-ref"><a href="#footnote7">[7:2]</a><a class="footnote-anchor" id="footnote-ref7:2"></a></sup></td><td>⚠️<sup class="footnote-ref"><a href="#footnote7">[7:3]</a><a class="footnote-anchor" id="footnote-ref7:3"></a></sup></td></tr><tr><td>Move detection<sup class="footnote-ref"><a href="#footnote8">[8]</a><a class="footnote-anchor" id="footnote-ref8"></a></sup></td><td>✅</td><td>❌</td><td>⚠️<sup class="footnote-ref"><a href="#footnote9">[9]</a><a class="footnote-anchor" id="footnote-ref9"></a></sup></td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>Chunked transfer<sup class="footnote-ref"><a href="#footnote10">[10]</a><a class="footnote-anchor" id="footnote-ref10"></a></sup></td><td>✅</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td></tr><tr><td>Metadata syncing<sup class="footnote-ref"><a href="#footnote11">[11]</a><a class="footnote-anchor" id="footnote-ref11"></a></sup></td><td>✅</td><td>⚠️<sup class="footnote-ref"><a href="#footnote12">[12]</a><a class="footnote-anchor" id="footnote-ref12"></a></sup></td><td>✅</td><td>❌</td><td>❌</td><td>❌</td></tr><tr><td>Encryption<sup class="footnote-ref"><a href="#footnote13">[13]</a><a class="footnote-anchor" id="footnote-ref13"></a></sup></td><td>✅</td><td>✅</td><td>❌</td><td>❌</td><td>❌</td><td>❌</td></tr></tbody></table><h2 id="webdav-performance" tabindex="-1">WebDAV Performance <a class="header-anchor" href="#webdav-performance" aria-label="Permalink to “WebDAV Performance”">​</a></h2><ul><li><strong>Obsidian version</strong>: 1.13.4</li><li><strong>Operating system</strong>: NixOS 26.11</li><li><strong>CPU single core score</strong>: around 1700</li><li><strong>Backend</strong>: Self-hosted Nextcloud WebDAV<sup class="footnote-ref"><a href="#footnote9">[9:1]</a><a class="footnote-anchor" id="footnote-ref9:1"></a></sup></li><li><strong>Average ping</strong>: 400 ms</li><li><strong>Average upload speed</strong>: 3 MiB/s</li><li><strong>Average download speed</strong>: 5 MiB/s</li></ul><table tabindex="0"><thead><tr><th>Item</th><th>Sync Engine</th><th>Remotely Save</th><th>Nextcloud Sync</th></tr></thead><tbody><tr><td>Version</td><td>3.0.0 + <code>webdav</code> module 0.1.7</td><td>0.5.25</td><td>0.7.38</td></tr><tr><td>2000 files upload</td><td><strong>9.43 min</strong></td><td>16.4 min</td><td>17.95 min</td></tr><tr><td>2000 files download</td><td>5.87 min</td><td>13.68 min</td><td><strong>5.22 min</strong></td></tr><tr><td>Daily simulation<br>(Original, 10 rounds)</td><td>Min: <strong>1.04 s</strong><br>Median: <strong>1.44 s</strong><br>Max: <strong>48.56 s</strong></td><td>Min: 99 s<br>Median: 129 s<br>Max: 326 s</td><td>Min: 1.27 s<br>Median: 2.75 s<br>Max: 60.55 s</td></tr><tr><td>Daily simulation<br>(Replica, 10 rounds)</td><td>Min: 1.06 s<br>Median: <strong>1.72 s</strong><br>Max: <strong>3.49 s</strong></td><td>Min: 111 s<br>Median: 117 s<br>Max: 204 s</td><td>Min: <strong>0.4 s</strong><br>Median: 3.94 s<br>Max: 55.33 s</td></tr><tr><td>Correctness validation</td><td>0 errors</td><td>0 errors</td><td><span style="color:var(--rose);font-weight:bold;">98 errors</span></td></tr></tbody></table><p>In terms of syncing performance, Sync Engine is visibly faster than Remotely Save in terms of full upload and download. In the more realistic daily sync test, Remotely Save fails catastrophically and Sync Engine is around <strong>100x faster</strong> than Remotely Save.</p><p>Although claimed to be optimized for Nextcloud, Nextcloud Sync still shows visible disadvantage in terms of performance compared with Sync Engine. More importantly, it <strong>fails to sync 98 original files or changes to the replica</strong>, and many errors appeared during the testing process.</p><h2 id="s3-performance" tabindex="-1">S3 Performance <a class="header-anchor" href="#s3-performance" aria-label="Permalink to “S3 Performance”">​</a></h2><ul><li><strong>Obsidian version</strong>: 1.14.5</li><li><strong>Operating system</strong>: NixOS 26.11</li><li><strong>CPU single core score</strong>: around 1700</li><li><strong>Backend</strong>: Self-hosted RustFs 1.0.4<sup class="footnote-ref"><a href="#footnote9">[9:2]</a><a class="footnote-anchor" id="footnote-ref9:2"></a></sup></li><li><strong>Average ping</strong>: 401.87 ms</li><li><strong>Average upload speed</strong>: 2.79 MiB/s</li><li><strong>Average download speed</strong>: 4.55 MiB/s</li><li><strong>S3 pricing standard</strong>: AWS S3 <code>us-east-1</code>, publication 2026-10-15</li></ul><table tabindex="0"><thead><tr><th>Item</th><th>Sync Engine</th><th>Remotely Save<sup class="footnote-ref"><a href="#footnote14">[14]</a><a class="footnote-anchor" id="footnote-ref14"></a></sup></th></tr></thead><tbody><tr><td>Version</td><td>3.3.4 + S3 module 0.2.3</td><td>0.5.25</td></tr><tr><td>2000 files upload</td><td><strong>3.95 min</strong></td><td>6.3 min</td></tr><tr><td>2000 files download</td><td><strong>2.42 min</strong></td><td>3.87 min</td></tr><tr><td>Daily simulation<br>(Original, 10 rounds)</td><td>Min: <strong>0.37 s</strong><br>Median: <strong>0.7 s</strong><br>Max: <strong>7.63 s</strong></td><td>Min: 2.16 s<br>Median: 3.1 s<br>Max: 76.12 s</td></tr><tr><td>Daily simulation<br>(Replica, 10 rounds)</td><td>Min: <strong>1.4 s</strong><br>Median: <strong>1.71 s</strong><br>Max: <strong>6.17 s</strong></td><td>Min: 1.87 s<br>Median: 2.68 s<br>Max: 32.4 s</td></tr><tr><td>Correctness validation</td><td>0 errors</td><td>0 errors</td></tr><tr><td>Total S3 cost</td><td><strong>$0.0585</strong></td><td>$0.0702</td></tr></tbody></table><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="footnote1" class="footnote-item"><p>Whether the author has made every controllable component that affects the plugins functioning free and open-source. <a href="#footnote-ref1" class="footnote-backref">↩︎</a></p></li><li id="footnote2" class="footnote-item"><p>Entire sync core is proprietary but source code is available. <a href="#footnote-ref2" class="footnote-backref">↩︎</a></p></li><li id="footnote3" class="footnote-item"><p>Nutstore server and the SSO sign-on dependency are not transparent. <a href="#footnote-ref3" class="footnote-backref">↩︎</a></p></li><li id="footnote4" class="footnote-item"><p>The time by which the plugin delays the cold start of Obsidian App. <a href="#footnote-ref4" class="footnote-backref">↩︎</a></p></li><li id="footnote5" class="footnote-item"><p>Measured with a module loaded. <a href="#footnote-ref5" class="footnote-backref">↩︎</a></p></li><li id="footnote6" class="footnote-item"><p>Can (be configured to) sync arbitrary files in directories with a leading dot, such as the Obsidian config folder <code>.obsidian/</code>. <a href="#footnote-ref6" class="footnote-backref">↩︎</a></p></li><li id="footnote7" class="footnote-item"><p>Only specific files under <code>.obsidian</code> can sync. <a href="#footnote-ref7" class="footnote-backref">↩︎</a> <a href="#footnote-ref7:1" class="footnote-backref">↩︎</a> <a href="#footnote-ref7:2" class="footnote-backref">↩︎</a> <a href="#footnote-ref7:3" class="footnote-backref">↩︎</a></p></li><li id="footnote8" class="footnote-item"><p>Correctly detects file movements instead of delete + download / upload. <a href="#footnote-ref8" class="footnote-backref">↩︎</a></p></li><li id="footnote9" class="footnote-item"><p>During local testing, the connection is delayed and bandwidth is limited to simulate middle-to-low network quality. <a href="#footnote-ref9" class="footnote-backref">↩︎</a> <a href="#footnote-ref9:1" class="footnote-backref">↩︎</a> <a href="#footnote-ref9:2" class="footnote-backref">↩︎</a></p></li><li id="footnote10" class="footnote-item"><p>Downloads / uploads large files in chunks so that the machine doesn&#39;t crash when dealing with large files. <a href="#footnote-ref10" class="footnote-backref">↩︎</a></p></li><li id="footnote11" class="footnote-item"><p>Preserves modification and creation time across devices. <a href="#footnote-ref11" class="footnote-backref">↩︎</a></p></li><li id="footnote12" class="footnote-item"><p>Only works on OneDrive. <a href="#footnote-ref12" class="footnote-backref">↩︎</a></p></li><li id="footnote13" class="footnote-item"><p>Supports encrypting files before uploading. <a href="#footnote-ref13" class="footnote-backref">↩︎</a></p></li><li id="footnote14" class="footnote-item"><p>&quot;Generate Folder Object&quot; is enabled to match the benchmark&#39;s correctness first standard. <a href="#footnote-ref14" class="footnote-backref">↩︎</a></p></li></ol></section>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};